UPDATE sync_task
SET name = #{name}, source_datasource_id = #{sourceDatasourceId}, source_database = #{sourceDatabase},
    target_datasource_id = #{targetDatasourceId}, target_database = #{targetDatabase},
    config = #{config}, notify_config = #{notifyConfig}, description = #{description},
    update_by = #{updateBy}, update_date = #{updateDate}
WHERE id = #{id}
